"""Triton Inference Server model repository.

Triton serves the exported ONNX model directly. The project generates a ready-to-use model
repository with a ``config.pbtxt`` and prints the ``docker run`` command; the client side is
described in the README ("Infer" section).
"""

from __future__ import annotations

import shutil
from pathlib import Path

from omegaconf import DictConfig

from lake_segmentation.logging_utils import get_logger
from lake_segmentation.models.bundle import load_bundle

LOGGER = get_logger("serving.triton")

CONFIG_TEMPLATE = """\
# Generated by `python commands.py prepare-triton` (do not edit by hand).
name: "{model_name}"
platform: "onnxruntime_onnx"
max_batch_size: {max_batch_size}

input [
  {{
    name: "{input_name}"
    data_type: {dtype}
    dims: [ {dims} ]
  }}
]

output [
  {{
    name: "{output_name}"
    data_type: {dtype}
    dims: [ 1, {tile_size}, {tile_size} ]
  }}
]

instance_group [
  {{
    kind: KIND_GPU
    count: 1
  }}
]

dynamic_batching {{
  preferred_batch_size: [ {preferred_batch} ]
  max_queue_delay_microseconds: 2000
}}
"""


def prepare_repository(cfg: DictConfig) -> Path:
    """Create ``<repository>/<model_name>/1/model.onnx`` and the ``config.pbtxt``."""

    serving_cfg = cfg.triton
    model_name = str(serving_cfg.model_name)
    repository = Path(serving_cfg.repository_dir)
    version_dir = repository / model_name / "1"
    version_dir.mkdir(parents=True, exist_ok=True)

    onnx_path = Path(serving_cfg.onnx_model)
    if not onnx_path.is_file():
        raise FileNotFoundError(
            f"ONNX model not found at {onnx_path}. Run `python commands.py export-onnx` first."
        )
    shutil.copy2(onnx_path, version_dir / "model.onnx")

    bundle = load_bundle(Path(cfg.triton.get("bundle") or cfg.infer.bundle))
    tile_size = int(bundle["postprocessing"]["tile_size"])
    band_count = len(bundle["preprocessing"]["band_order"])
    config_text = CONFIG_TEMPLATE.format(
        model_name=model_name,
        max_batch_size=int(serving_cfg.max_batch_size),
        input_name=str(serving_cfg.input_name),
        output_name=str(serving_cfg.output_name),
        dtype=str(serving_cfg.dtype),
        dims=", ".join(str(value) for value in (band_count, tile_size, tile_size)),
        tile_size=tile_size,
        preferred_batch=min(int(serving_cfg.max_batch_size), 4),
    )
    config_path = repository / model_name / "config.pbtxt"
    config_path.write_text(config_text, encoding="utf-8")

    LOGGER.info("Triton model repository prepared at %s", repository)
    LOGGER.info(
        "Start the server with:\n  docker run --gpus all --rm -p %d:8000 -p %d:8001 -p 8002:8002 "
        "-v %s:/models --name triton-lake nvcr.io/nvidia/tritonserver:24.08-py3 "
        "tritonserver --model-repository=/models",
        int(serving_cfg.port),
        int(serving_cfg.http_port),
        repository.resolve(),
    )
    return repository


def client_snippet(cfg: DictConfig) -> str:
    """Return a copy-pasteable Triton client example."""

    serving_cfg = cfg.triton
    bundle = load_bundle(Path(serving_cfg.get("bundle") or cfg.infer.bundle))
    tile_size = int(bundle["postprocessing"]["tile_size"])
    band_count = len(bundle["preprocessing"]["band_order"])
    threshold = float(bundle["postprocessing"]["threshold"])
    url = f"{serving_cfg.host}:{serving_cfg.port}"
    return f"""\
import numpy as np
import tritonclient.http as httpclient

client = httpclient.InferenceServerClient(url="{url}")
image = np.random.rand(1, {band_count}, {tile_size}, {tile_size}).astype(np.float32)
inp = httpclient.InferInput("{serving_cfg.input_name}", image.shape, "FP32")
inp.set_data_from_numpy(image)
result = client.infer("{serving_cfg.model_name}", inputs=[inp])
probabilities = result.as_numpy("{serving_cfg.output_name}")  # (1, 1, {tile_size}, {tile_size})
mask = probabilities[0, 0] > {threshold}
"""
